import java.rmi.Remote;
import java.rmi.RemoteException;

public interface Calculator extends Remote {
    double add(double left, double right) throws RemoteException;

    double subtract(double left, double right) throws RemoteException;

    double multiply(double left, double right) throws RemoteException;

    double divide(double left, double right) throws RemoteException;
}

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;

public class CalculatorImpl extends UnicastRemoteObject implements Calculator {
    public CalculatorImpl() throws RemoteException {
        super();
    }

    @Override
    public double add(double left, double right) {
        return left + right;
    }

    @Override
    public double subtract(double left, double right) {
        return left - right;
    }

    @Override
    public double multiply(double left, double right) {
        return left * right;
    }

    @Override
    public double divide(double left, double right) {
        if (right == 0) {
            throw new IllegalArgumentException("Cannot divide by zero");
        }
        return left / right;
    }
}

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;

public class CalculatorServer {
    public static void main(String[] args) throws Exception {
        Calculator calculator = new CalculatorImpl();
        Registry registry = LocateRegistry.createRegistry(1099);
        registry.rebind("CalculatorService", calculator);

        System.out.println("Calculator RMI server is running on port 1099.");
        System.out.println("Press Ctrl+C to stop the server.");
    }
}

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;

public class CalculatorClient {
    public static void main(String[] args) throws Exception {
        String operation = args.length > 0 ? args[0].toLowerCase() : "add";
        double left = args.length > 1 ? Double.parseDouble(args[1]) : 10;
        double right = args.length > 2 ? Double.parseDouble(args[2]) : 5;

        Registry registry = LocateRegistry.getRegistry("localhost", 1099);
        Calculator calculator = (Calculator) registry.lookup("CalculatorService");
        double result;

        switch (operation) {
            case "add" -> result = calculator.add(left, right);
            case "subtract" -> result = calculator.subtract(left, right);
            case "multiply" -> result = calculator.multiply(left, right);
            case "divide" -> result = calculator.divide(left, right);
            default -> throw new IllegalArgumentException(
                    "Unknown operation: " + operation
                            + ". Use add, subtract, multiply, or divide.");
        }

        System.out.printf("%s %s %s = %s%n", left, operation, right, result);
    }
}

